package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RefreshTokenTtlSecondsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property refresh token ttl seconds of tenant config ")
  void test_refresh_token_ttl_seconds_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> RefreshTokenTtlSecondsVO.tryFrom(null));
    Assertions.assertEquals(1, RefreshTokenTtlSecondsVO.from(1).getRefreshTokenTtlSeconds());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RefreshTokenTtlSecondsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RefreshTokenTtlSecondsVO.from(1).toString());
  }
}
